/*
 * A267813  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 219" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267813
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = 0 if n = m*(m+1) for some integer m > 0, otherwise 1
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is 1 except at the indices 2,6,12,20,30,42,… which are the
 * products of consecutive integers m*(m+1) (with m ≥ 1).  This yields the
 * values listed in the OEIS entry and matches all further terms. */

#include <stdint.h>

/* Integer square root: floor(sqrt(n)) for n up to 2^64-1. */
static idx_t isqrt(idx_t n)
{
    idx_t low = 0;
    idx_t high = 0xFFFFFFFFULL;           /* sqrt(2^64-1) < 2^32 */
    while (low <= high) {
        idx_t mid = (low + high) >> 1;
        idx_t sq  = mid * mid;
        if (sq <= n) {
            low = mid + 1;
        } else {
            if (mid == 0) break;
            high = mid - 1;
        }
    }
    return low - 1;
}

seq_t a(idx_t n)
{
    idx_t m = isqrt(n);                     /* m = floor(sqrt(n)) */
    if (m > 0 && m * (m + 1) == n) {
        return (seq_t)0;
    }
    return (seq_t)1;
}
